<?php

namespace App\Console\Commands;

use Illuminate\Console\Command;
use Illuminate\Filesystem\Filesystem;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
use Illuminate\Support\Str;
use Symfony\Component\Console\Attribute\AsCommand;

/**
 * Removes a manage feature generated by make:manage: every generated file plus
 * the registrations (routes, binding, routes.js, vite, sidebar, dashboard lang).
 * Mirror of MakeManage; keep both in sync. See .ai/rules/manage-generator.md.
 */
#[AsCommand(name: 'remove:manage')]
class RemoveManage extends Command
{
    protected $signature = 'remove:manage
        {name : Singular entity name, e.g. Product or ProductCategory}
        {--drop-table : Also drop the database table and its migration records}
        {--force : Skip the confirmation prompt (only after the user explicitly approved the deletion)}';

    protected $description = 'Delete a manage feature generated by make:manage (files, routes, nav, lang, optionally the table).';

    public function __construct(private readonly Filesystem $files)
    {
        parent::__construct();
    }

    public function handle(): int
    {
        $model = Str::studly($this->argument('name'));
        $singular = Str::kebab($model);
        $slug = Str::plural($singular);
        $table = Str::snake(Str::plural($model));

        $paths = $this->paths($model, $slug, $singular, $table);
        $existing = array_values(array_filter($paths, fn ($p) => $this->files->exists(base_path($p))));

        if ($existing === [] && ! $this->isRegistered($slug)) {
            $this->error("No manage feature found for {$model}.");

            return self::FAILURE;
        }

        $this->warn("This will permanently delete the {$model} manage feature:");
        array_map(fn ($p) => $this->line("  - {$p}"), $existing);
        $this->line('  - registrations in routes/web.php, routes/api.php, AppServiceProvider, routes.js, vite.config.js, config/sidebar.php, lang/*/dashboard.php');

        if ($this->option('drop-table')) {
            $this->line("  - database table \"{$table}\" (data is lost) and its migration records");
        }

        if (! $this->option('force') && ! $this->confirm('Continue?', false)) {
            $this->line('Aborted.');

            return self::FAILURE;
        }

        foreach ($existing as $path) {
            $this->files->isDirectory(base_path($path))
                ? $this->files->deleteDirectory(base_path($path))
                : $this->files->delete(base_path($path));
            $this->line("  <info>deleted</info> {$path}");
        }

        $this->unregisterRoutes($model, $slug);
        $this->strip('app/Providers/AppServiceProvider.php', [
            "/^use App\\\\Repositories\\\\{$model}\\\\.*\\n/m",
            "/^.*{$model}RepositoryInterface::class.*\\n/m",
        ]);
        $this->unregisterRoutesJs($slug, Str::camel(Str::plural($model)), Str::camel($model));
        $this->strip('vite.config.js', ["/^.*resources\\/js\\/{$slug}\\/(index|form)\\.js.*\\n/m"]);
        $this->unregisterSidebar($slug);

        foreach (['en', 'id'] as $locale) {
            $this->strip("lang/{$locale}/dashboard.php", ["/^\\s*'{$slug}' => .*\\n/m"]);
        }

        if ($this->option('drop-table')) {
            $this->dropTable($table);
        }

        $this->info("{$model} manage feature removed.");
        $this->line('Next: run "vendor/bin/pint --dirty", "npm run build" and the test suite.');

        return self::SUCCESS;
    }

    /**
     * @return array<int, string>
     */
    private function paths(string $model, string $slug, string $singular, string $table): array
    {
        $migrations = array_map(
            fn ($file) => 'database/migrations/'.basename($file),
            $this->files->glob(base_path("database/migrations/*_{$table}_table.php")) ?: [],
        );

        return [
            "app/Models/{$model}.php",
            ...$migrations,
            "database/factories/{$model}Factory.php",
            "app/Repositories/{$model}",
            "app/Services/{$model}ManagementService.php",
            "app/Http/Requests/{$model}",
            "app/Http/Resources/{$model}Resource.php",
            "app/Http/Controllers/Api/{$model}Controller.php",
            "app/Http/Controllers/{$model}PageController.php",
            "app/Traits/{$model}",
            "resources/views/{$slug}",
            "resources/views/components/organisms/{$singular}-form-skeleton.blade.php",
            "resources/js/{$slug}",
            "lang/en/{$slug}.php",
            "lang/id/{$slug}.php",
            "tests/Feature/{$model}ManagementTest.php",
            "tests/playwright/{$slug}.spec.ts",
        ];
    }

    private function isRegistered(string $slug): bool
    {
        return str_contains($this->files->get(base_path('routes/web.php')), "'{$slug}.index'")
            || str_contains($this->files->get(base_path('routes/api.php')), "'{$slug}'");
    }

    /**
     * @param  array<int, string>  $patterns
     */
    private function strip(string $path, array $patterns): void
    {
        $full = base_path($path);

        if (! $this->files->exists($full)) {
            return;
        }

        $contents = $this->files->get($full);
        $updated = preg_replace($patterns, '', $contents);

        if ($updated !== $contents) {
            $this->files->put($full, $updated);
            $this->line("  <info>updated</info> {$path}");
        }
    }

    /**
     * Match a `Route::prefix('{slug}')->group(...)` block that only holds routes of the given controller.
     */
    private function prefixGroupPattern(string $slug, string $controller): string
    {
        return "/^[ ]*Route::prefix\\('{$slug}'\\)->group\\(function \\(\\): void \\{\\n(?:(?![ ]*\\}\\);\\n)[^\\n]*{$controller}[^\\n]*\\n|[ ]+->[^\\n]*\\n)*[ ]*\\}\\);\\n/m";
    }

    private function unregisterRoutes(string $model, string $slug): void
    {
        $this->strip('routes/web.php', [
            "/^use App\\\\Http\\\\Controllers\\\\{$model}PageController;\\n/m",
            "/^\\s*Route::get\\('\\/{$slug}[^\\n]*{$model}PageController[^\\n]*\\n/m",
            $this->prefixGroupPattern($slug, $model.'PageController'),
        ]);

        $this->strip('routes/api.php', [
            "/^use App\\\\Http\\\\Controllers\\\\Api\\\\{$model}Controller;\\n/m",
            "/^\\s*Route::delete\\('\\/{$slug}', \\[{$model}Controller::class[^\\n]*\\n/m",
            $this->prefixGroupPattern($slug, $model.'Controller'),
            "/^\\s*Route::post\\('\\/{$slug}\\/generate', \\[{$model}Controller::class.*?->name\\('{$slug}\\.generate'\\);\\n/ms",
            "/^\\s*Route::resource\\('{$slug}', {$model}Controller::class\\).*?->names\\('{$slug}'\\);\\n/ms",
        ]);

        $this->tidyBlankLines(['routes/web.php', 'routes/api.php']);
    }

    /**
     * Drop the blank line the generator inserted before a block once the block is gone.
     *
     * @param  array<int, string>  $paths
     */
    private function tidyBlankLines(array $paths): void
    {
        foreach ($paths as $path) {
            $contents = $this->files->get(base_path($path));
            $updated = preg_replace(
                ['/\n{3,}/', '/\n[ \t]*\n(\s*\}\);)/', '/[ \t]+$/m'],
                ["\n\n", "\n$1", ''],
                $contents,
            );

            if ($updated !== $contents) {
                $this->files->put(base_path($path), $updated);
            }
        }
    }

    private function unregisterRoutesJs(string $slug, string $key, string $var): void
    {
        $this->strip('resources/js/routes.js', [
            "/^    {$key}: \\{\\n.*?^    \\},\\n/ms",
            "/^        {$key}: '\\/{$slug}',\\n/m",
            "/^        {$var}Create: .*\\n/m",
            "/^        {$var}Edit: .*\\n/m",
        ]);
    }

    private function unregisterSidebar(string $slug): void
    {
        $path = 'config/sidebar.php';

        $this->strip($path, ["/^\\s*\\['label' => 'dashboard\\.nav\\.{$slug}'.*\\n/m"]);

        // The generator shares one "cube" icon; drop it once nothing uses it.
        if (substr_count($this->files->get(base_path($path)), "'icon' => 'cube'") === 0) {
            $this->strip($path, ["/^\\s*'cube' => .*\\n/m"]);
        }
    }

    private function dropTable(string $table): void
    {
        Schema::dropIfExists($table);
        DB::table('migrations')->where('migration', 'like', "%\\_{$table}\\_table")->delete();

        $this->line("  <info>dropped</info> table {$table}");
    }
}
